def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (everything after '+')
        if '+' in v:
            v, _ = v.split('+', 1)

        # Split into core version and pre-release
        if '-' in v:
            core, prerelease = v.split('-', 1)
        else:
            core = v
            prerelease = None

        # Parse core version
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease:
            identifiers = prerelease.split('.')
            prerelease_tuple = []
            for identifier in identifiers:
                if identifier.isdigit():
                    prerelease_tuple.append((0, int(identifier)))
                else:
                    prerelease_tuple.append((1, identifier))
            prerelease_tuple = tuple(prerelease_tuple)
        else:
            # No pre-release sorts after pre-release
            prerelease_tuple = None

        return (major, minor, patch, prerelease_tuple)

    def sort_key(v):
        major, minor, patch, prerelease = parse_version(v)
        # Return tuple where:
        # - (major, minor, patch) sorts numerically
        # - prerelease is None if absent (sorts after non-None)
        # - if prerelease exists, use the tuple for comparison
        if prerelease is None:
            return (major, minor, patch, (1,))
        else:
            return (major, minor, patch, (0, prerelease))

    return sorted(versions, key=sort_key)

